<script>
export default {
    data() {
        return {
            leaveSearchMode: false,
            leaveSearchModel: "",
            HrLeaves: [],
            HrLeavesTypes: [],
            leaglConditions: [
              { name: "Yes", value: 1 },
              { name: "No", value: 0 },
            ],
            isLegal: false,
            leaveType: {
              date: null,
              descr: null,
            },
            selectedLeaveTypeEmployee: {},
            leavesLimit: 2,
            leavesPage: 1,
            leavesTotalPages: 0,
        }
    },
    methods: {
        getHrLeaves(page, tabClick) {
            console.log("step 263 :",this.HrLeaves.length,tabClick  );
            if (this.HrLeaves.length > 0 && tabClick) return;
            this.http
              .post("hr-leaves/employee/pagination", {
                limit: this.leavesLimit,
                page,
                id: parseInt(this.$route.params.id),
              })
              .then((res) => {
                this.leavesPage = page;
                this.leavesTotalPages = Math.ceil(res.tot / this.leavesLimit);
                this.HrLeaves = res.data;
              });
        },
        onFileChange(e) {
      var files = e.target.files || e.dataTransfer.files;
      if (!files.length) return;
      this.createImage(files[0], true);
    },
        deleteHrLeaves(app) {
          var data = {
            title: "popups.delete",
            msg: "popups.delmessage",
          };
          this.popup.confirm(data).then((resp) => {
            if (resp) {
              this.http
                .post("hr-leaves/delete-leave-file", {
                  id: app.id,
                  file: app?.file,
                })
                .then(() => {
                  this.getHrLeaves(this.leavesPage, false);
                });
            }
          });
        },
        getLeaves(app) {
          if (app) {
            this.selectedLeaveTypeEmployee = app;
          }
          if (this.HrLeavesTypes.length <= 0) {
            this.http.post("hr-leave-types/get-types", {}).then((resp) => {
              if (resp.status) {
                this.HrLeavesTypes = resp.data;
                this.HrLeavesTypes.push({ name: "other", id: null });
              }
            });
            return;
          }
        },
        addHrLeaves() {
            var data = {
                title: this.$t("popups.add"),
                inputs: [
                    {
                        model: "start_date",
                        type: "date",
                        label: this.$t("hr_holidays.start_date"),
                        required: true,
                    },
                    {
                        model: "end_date",
                        type: "date",
                        label: this.$t("hr_holidays.end_date"),
                        required: true,
                    },
                    {
                        model: "hr_leave_type_id",
                        type: "select",
                        label: this.$t("hr_leaves.hr_leave_type_id"),
                        options: this.HrLeavesTypes.map(item => ({ value: item.id, label: item.name })),
                        required: true,
                    },
                    {
                        model: "descr",
                        type: "textarea",
                        label: this.$t("hr_leaves.descr"),
                    },
                    {
                      model: "file",
                      type: "file",
                      label: this.$t("hr_leaves.file"),
                    }
                ],
                buttons: [
                  {
                    text: "popups.add",
                    closer: true,
                    color: "primary",
                    handler: (obj) => {
                      obj.hr_employee_id = parseInt(this.$route.params.id);
                      console.log("obj", obj);
                      if (!obj.hr_leave_type_id) {
                        delete obj.hr_leave_type_id;
                      }
                      if(obj?.file) {
                        this.http.do("hr-leaves", obj).then(() => {
                          this.getHrLeaves(this.leavesPage, false);
                          this.leaveType = { date: null, descr: null };
                        });
                      } else {
                        this.http.post("hr-leaves", obj).then(() => {
                          this.getHrLeaves(this.leavesPage, false);
                          this.leaveType = { date: null, descr: null };
                        });
                      }
                    },
                  },
                  {
                    text: "popups.cancel",
                    closer: true,
                    color: "danger",
                    handler: () => {
                      console.log("Like Clicked");
                    },
                  },
                ],
              };
            this.popup.modal(data);  
        },
        editHrLeaves() {
          this.http
            .put(
              "hr-leaves",
              this.selectedLeaveTypeEmployee.id,
              this.selectedLeaveTypeEmployee
            )
            .then(() => {
             this.getHrLeaves(this.leavesPage, false)
            });
        },
        showIsLeagal() {
          if (this.leaveType.hr_leave_type_id) {
            this.isLegal = false;
            return;
          }
          this.isLegal = true;
          console.log({
            type: this.leaveType,
            types: this.HrLeavesTypes,
            leagal: this.isLegal,
          });
        },
        leaveSearch() {
          if(!this.leaveSearchModel.length) return this.getHrLeaves(this.page,false);
          this.leaveSearchMode = true;
          this.leavesTotalPages = 0;
          this.http
            .post("hr-leaves/leave-search", {
              search: this.leaveSearchModel,
              limit: this.limit,
              page: this.page,
              col: "descr",
            })
            .then((res) => {
              this.HrLeaves = res.data;
              console.log("######## files", this.HrLeavesTypes);
            });
        },
    },
    mounted() {
        this.getHrLeaves(1, true);
        this.getLeaves(false);
    },
}
</script>
